"""核心逻辑：输入校验、夹子检测、打包排序与回滚记录。

只依赖标准库；字符串一律原样比较（区分大小写、不去空白）。
"""

import json

# 错误码（同时作为 stderr 中输出的 code）
BAD_JSON = "BAD_JSON"
BAD_SCHEMA = "BAD_SCHEMA"
DUP_HASH = "DUP_HASH"
DUP_NONCE = "DUP_NONCE"
BAD_SIDE = "BAD_SIDE"
BAD_SIM = "BAD_SIM"

# 回滚原因
REVERT = "REVERT"
DEPENDENT_NONCE = "DEPENDENT_NONCE"


class ShieldError(Exception):
    """携带错误码的校验失败。"""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _is_nonneg_int(value):
    # JSON 非负整数；bool 是 int 的子类，必须显式排除
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _is_str(value):
    return isinstance(value, str)


def parse_input(raw):
    """解析并校验输入，返回 (id, transactions)；失败抛 ShieldError。"""
    try:
        data = json.loads(raw)
    except (ValueError, UnicodeDecodeError):
        raise ShieldError(BAD_JSON)

    if not isinstance(data, dict):
        raise ShieldError(BAD_SCHEMA)
    if "id" not in data or not _is_str(data["id"]):
        raise ShieldError(BAD_SCHEMA)
    txs = data.get("transactions")
    if not isinstance(txs, list):
        raise ShieldError(BAD_SCHEMA)

    parsed = []
    seen_hash = set()
    # from -> 已出现的 nonce 集合
    seen_nonce = {}

    for tx in txs:
        if not isinstance(tx, dict):
            raise ShieldError(BAD_SCHEMA)
        for key in ("hash", "from", "nonce", "fee", "token", "side", "sim"):
            if key not in tx:
                raise ShieldError(BAD_SCHEMA)
        h = tx["hash"]
        sender = tx["from"]
        nonce = tx["nonce"]
        fee = tx["fee"]
        token = tx["token"]
        side = tx["side"]
        sim = tx["sim"]

        if not all(_is_str(v) for v in (h, sender, token)):
            raise ShieldError(BAD_SCHEMA)
        if not _is_nonneg_int(nonce) or not _is_nonneg_int(fee):
            raise ShieldError(BAD_SCHEMA)

        # hash 重复先于 side / sim 判定
        if h in seen_hash:
            raise ShieldError(DUP_HASH)
        seen_hash.add(h)

        # side / sim 的合法性先于 nonce 重复判定
        if side not in ("buy", "sell"):
            raise ShieldError(BAD_SIDE)
        if sim not in ("success", "revert"):
            raise ShieldError(BAD_SIM)

        sender_nonces = seen_nonce.setdefault(sender, set())
        if nonce in sender_nonces:
            raise ShieldError(DUP_NONCE)
        sender_nonces.add(nonce)

        parsed.append(
            {
                "hash": h,
                "from": sender,
                "nonce": nonce,
                "fee": fee,
                "token": token,
                "side": side,
                "sim": sim,
            }
        )

    return data["id"], parsed


def detect_sandwiches(txs):
    """返回命中列表，每项为 (i, j, k)，按 i（再 j、k）升序。

    对 i<j<k：i、k 同 from，i 为 buy、k 为 sell；j 不同 from 且为 buy；
    token 相同且三者 sim 均为 success。
    """
    hits = []
    n = len(txs)
    for i in range(n - 2):
        ti = txs[i]
        if ti["side"] != "buy" or ti["sim"] != "success":
            continue
        for k in range(i + 2, n):
            tk = txs[k]
            if (
                tk["side"] != "sell"
                or tk["sim"] != "success"
                or tk["from"] != ti["from"]
                or tk["token"] != ti["token"]
            ):
                continue
            for j in range(i + 1, k):
                tj = txs[j]
                if (
                    tj["side"] == "buy"
                    and tj["sim"] == "success"
                    and tj["from"] != ti["from"]
                    and tj["token"] == ti["token"]
                ):
                    hits.append((i, j, k))
    return hits


def _rollback_entry(tx, at, reason):
    return {"hash": tx["hash"], "at": at, "reason": reason}


def build_no_sandwich(txs):
    """无夹子时：排除 revert 与同 from 中 nonce 更大的交易，其余排序打包。

    rollback 按原位置记录；order 按 fee 降序、hash 升序。
    """
    # 每个 from 的最大 nonce
    max_nonce = {}
    for tx in txs:
        sender = tx["from"]
        if sender not in max_nonce or tx["nonce"] > max_nonce[sender]:
            max_nonce[sender] = tx["nonce"]

    rollback = []
    survivors = []
    for at, tx in enumerate(txs):
        if tx["sim"] == "revert":
            rollback.append(_rollback_entry(tx, at, REVERT))
        elif tx["nonce"] < max_nonce[tx["from"]]:
            rollback.append(_rollback_entry(tx, at, DEPENDENT_NONCE))
        else:
            survivors.append(tx)

    # rollback 已天然按原位置升序
    survivors.sort(key=lambda tx: (-tx["fee"], tx["hash"]))
    order = [tx["hash"] for tx in survivors]
    dropped = [entry["hash"] for entry in rollback]
    return order, rollback, order, dropped


def _empty(value):
    """失败时“其余字段为空”：列表/字典给空容器。"""
    if isinstance(value, list):
        return []
    if isinstance(value, dict):
        return {}
    return ""


def process(raw):
    """处理输入文本，返回 (result_dict, error_code_or_None)。"""
    # id 不可得时为空字符串
    try:
        obj, _ = json.JSONDecoder().raw_decode(raw.lstrip() if isinstance(raw, str) else raw)
        ident = obj.get("id") if isinstance(obj, dict) else None
        ident = ident if isinstance(ident, str) else ""
    except Exception:
        ident = ""

    try:
        ident, txs = parse_input(raw)
    except ShieldError as exc:
        return error_result(ident, exc.code), exc.code

    hits_idx = detect_sandwiches(txs)
    if hits_idx:
        hits = [
            {
                "buy": txs[i]["hash"],
                "victim": txs[j]["hash"],
                "sell": txs[k]["hash"],
                "token": txs[i]["token"],
                "at": [i, j, k],
            }
            for (i, j, k) in hits_idx
        ]
        result = {
            "id": ident,
            "status": "rejected",
            "code": "SANDWICH_DETECTED",
            "order": [],
            "hits": hits,
            "rollback": [],
            "kept": [],
            "dropped": [],
        }
        return result, None

    order, rollback, kept, dropped = build_no_sandwich(txs)
    result = {
        "id": ident,
        "status": "ok",
        "code": "",
        "order": order,
        "hits": [],
        "rollback": rollback,
        "kept": kept,
        "dropped": dropped,
    }
    return result, None


def error_result(ident, code):
    return {
        "id": ident,
        "status": "error",
        "code": code,
        "order": [],
        "hits": [],
        "rollback": [],
        "kept": [],
        "dropped": [],
    }


def serialize(result):
    """确定性序列化：固定键顺序、无多余空白、末尾换行。"""
    return json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n"

